package cl.felipe.agrofrost.infrastructure.persistence;
import cl.felipe.agrofrost.domain.entity.Field; import cl.felipe.agrofrost.domain.valueobject.*; import org.junit.jupiter.api.Test; import static org.junit.jupiter.api.Assertions.*;
class InMemoryFieldRepositoryTest { private Field field(String id) { return new Field(new FieldId(id),new FieldName("North"),new Crop("Grapes"),new CriticalTemperature(0)); } @Test void savesFindsAndListsFieldsThroughAnIsolatedCollection() { InMemoryFieldRepository repository=new InMemoryFieldRepository(); Field field=field("f-1"); repository.save(field); assertEquals(field, repository.findById(field.id()).orElseThrow()); assertEquals(1, repository.findAll().size()); assertThrows(UnsupportedOperationException.class, () -> repository.findAll().clear()); } @Test void returnsEmptyForUnknownAndRejectsNulls() { InMemoryFieldRepository repository=new InMemoryFieldRepository(); assertTrue(repository.findById(new FieldId("missing")).isEmpty()); assertThrows(NullPointerException.class, () -> repository.save(null)); assertThrows(NullPointerException.class, () -> repository.findById(null)); } }
